DECLARE
    v_now      timestamptz := p_ts;          -- می‌تونی اینجا به Asia/Tehran تبدیل کنی اگر لازم شد
    v_date     date        := v_now::date;
    v_time     time        := v_now::time;
		
		v_now_local  timestamp := (p_ts AT TIME ZONE 'Asia/Tehran');
  v_date_local date      := v_now_local::date;
  v_time_local time      := v_now_local::time;

    v_allowed  boolean := true;
    v_penalty  numeric := 1.0;              -- ۱ = بدون جریمه اضافه
    v_type     text    := 'none';

    v_admin_close_penalty  numeric;
    v_admin_penalty        numeric;
    v_time_block_exists    boolean := false;
    v_prayer_block_exists  boolean := false;

    -- ضرایب پیشنهادی برای محدودیت‌های زمانی/نماز (اگر بسته باشند)
    c_time_penalty   constant numeric := 10.0;
    c_prayer_penalty constant numeric := 8.0;
		
BEGIN
    ----------------------------------------------------------------------
    -- 1) محدودیت‌های ادمین (admin_restrictions)
    ----------------------------------------------------------------------
    -- 1.1) نوع close  → یعنی این موجودیت واقعاً بسته است
    SELECT MAX(r.penalty_w)
    INTO v_admin_close_penalty
    FROM admin_restrictions r
    WHERE
        r.is_active = true
        AND (r.starts_at IS NULL OR r.starts_at <= v_now)
        AND (r.ends_at   IS NULL OR v_now <= r.ends_at)
        AND (
              r.gender IS NULL
           OR r.gender = 'both'::gender_enum
           OR r.gender = p_gender
        )
        AND (
              r.modes IS NULL
           OR p_mode = ANY(r.modes)
        )
        AND r.restrict_type = 'close'
        AND (
                -- محدودیت مستقیم روی همین entity
                (r.target_table = p_entity_table AND r.target_id = p_entity_id)
             OR
                -- یا محدودیت عمومی روی یک محدوده/طبقه
                (
                    r.target_table IS NULL
                    AND r.target_id   IS NULL
                    AND (r.floor IS NULL OR r.floor = p_floor)
                    AND (
                           r.geom IS NULL
                        OR (p_geom IS NOT NULL AND ST_Contains(r.geom, p_geom))
                    )
                )
        );

    IF v_admin_close_penalty IS NOT NULL THEN
        v_allowed := false;
				v_penalty := GREATEST(COALESCE(v_penalty, 1.0), COALESCE(v_admin_close_penalty, 1.0));
        v_type    := 'admin_close';
    END IF;

    -- 1.2) نوع غیر close → به معنی «مجاز ولی با جریمه»
    SELECT MAX(r.penalty_w)
    INTO v_admin_penalty
    FROM admin_restrictions r
    WHERE
        r.is_active = true
        AND (r.starts_at IS NULL OR r.starts_at <= v_now)
        AND (r.ends_at   IS NULL OR v_now <= r.ends_at)
        AND (
              r.gender IS NULL
           OR r.gender = 'both'::gender_enum
           OR r.gender = p_gender
        )
        AND (
              r.modes IS NULL
           OR p_mode = ANY(r.modes)
        )
        AND r.restrict_type <> 'close'
        AND (
                (r.target_table = p_entity_table AND r.target_id = p_entity_id)
             OR (
                    r.target_table IS NULL
                    AND r.target_id   IS NULL
                    AND (r.floor IS NULL OR r.floor = p_floor)
                    AND (
                           r.geom IS NULL
                        OR (p_geom IS NOT NULL AND ST_Contains(r.geom, p_geom))
                    )
                )
        );

    IF v_admin_penalty IS NOT NULL THEN
				v_penalty := GREATEST(COALESCE(v_penalty, 1.0), COALESCE(v_admin_penalty, 1.0));
        IF v_type = 'none' THEN
            v_type := 'admin_penalty';
        ELSIF v_type <> 'admin_close' THEN
            -- اگر قبلاً نوع دیگری هم ست شده بود، بگیم mixed
            v_type := 'mixed';
        END IF;
    END IF;

    ----------------------------------------------------------------------
    -- 2) محدودیت‌های زمانی (access_time_restrictions)
    --    این‌ها را به صورت «بسته بودن در این زمان» تفسیر می‌کنیم.
    ----------------------------------------------------------------------
    SELECT EXISTS (
        SELECT 1
        FROM access_time_restrictions r
        WHERE
            r.entity_table = p_entity_table
            AND r.entity_id = p_entity_id
            AND (r.specific_date IS NULL OR r.specific_date = v_date)
            AND (
                    r.all_hours = true
                 OR (
                        r.start_time IS NOT NULL
                    AND r.end_time   IS NOT NULL
                    AND v_time >= r.start_time
                    AND v_time <  r.end_time
                 )
            )
            AND (
                    r.gender IS NULL
                 OR cardinality(r.gender) = 0
                 OR p_gender = ANY(r.gender)
                 OR 'both'::gender_enum = ANY(r.gender)
            )
    ) INTO v_time_block_exists;

    IF v_time_block_exists THEN
        v_allowed := false;
				v_penalty := GREATEST(COALESCE(v_penalty, 1.0), COALESCE(c_time_penalty, 1.0));

        IF v_type = 'none' THEN
            v_type := 'time';
        ELSIF v_type <> 'time' THEN
            v_type := 'mixed';
        END IF;
    END IF;

    ----------------------------------------------------------------------
    -- 3) محدودیت‌های نماز (access_prayer_restrictions)
    --    این بخش اسکلت است و به تابع زمان نماز نیاز دارد.
    --    فعلاً فقط TODO است؛ اگر تابع prayer windows رو اضافه کردی،
    --    این بخش را از حالت کامنت خارج کن.
    ----------------------------------------------------------------------

    -- نمونه‌ی پیشنهادی:
    -- یک تابع مثل:
    --   fn_prayer_windows(p_date date)
    -- که برای هر نماز، این خروجی را داشته باشد:
    --   (prayer_event text, center_time timestamptz)
    --
    -- سپس:
    /*
    SELECT EXISTS (
        SELECT 1
        FROM access_prayer_restrictions pr
        JOIN fn_prayer_windows(v_date) pw
             ON pw.prayer_event = pr.prayer_event
        WHERE
            pr.entity_table = p_entity_table
            AND pr.entity_id = p_entity_id
            AND (pr.specific_date IS NULL OR pr.specific_date = v_date)
            AND v_now BETWEEN
                (pw.center_time - make_interval(mins := pr.before_minutes))
                AND
                (pw.center_time + make_interval(mins := pr.after_minutes))
            AND (
                    pr.gender IS NULL
                 OR cardinality(pr.gender) = 0
                 OR p_gender = ANY(pr.gender)
                 OR 'both'::gender_enum = ANY(pr.gender)
            )
    ) INTO v_prayer_block_exists;
    */
		
		SELECT EXISTS (
    SELECT 1
    FROM access_prayer_restrictions pr
    WHERE pr.entity_table = p_entity_table
      AND pr.entity_id = p_entity_id
      AND (pr.specific_date IS NULL OR pr.specific_date = v_date)
      AND (
           pr.gender IS NULL OR cardinality(pr.gender)=0
        OR p_gender = ANY(pr.gender) OR 'both'::gender_enum = ANY(pr.gender)
      )
      AND (
        -- window check
        fn_prayer_event_time(v_date, pr.prayer_event) IS NOT NULL
        AND v_now_local BETWEEN
  (v_date_local::timestamp + fn_prayer_event_time(v_date_local, pr.prayer_event))
    - make_interval(mins => pr.before_minutes)
  AND
  (v_date_local::timestamp + fn_prayer_event_time(v_date_local, pr.prayer_event))
    + make_interval(mins => pr.after_minutes)

      )
  ) INTO v_prayer_block_exists;

    -- فعلاً تا وقتی تابع نماز را نداری، v_prayer_block_exists همیشه false می‌ماند.
    --v_prayer_block_exists := false;

    IF v_prayer_block_exists THEN
        v_allowed := false;
				v_penalty := GREATEST(COALESCE(v_penalty, 1.0), COALESCE(c_prayer_penalty, 1.0));
	
        IF v_type = 'none' THEN
            v_type := 'prayer';
        ELSIF v_type <> 'prayer' THEN
            v_type := 'mixed';
        END IF;
    END IF;

    ----------------------------------------------------------------------
    -- 4) خروجی
    ----------------------------------------------------------------------
    allowed          := COALESCE(v_allowed, true);
penalty_w        := COALESCE(v_penalty, 1.0);
restriction_type := COALESCE(v_type, 'none');

RETURN NEXT;
RETURN;

END;

