    ----------------------------------------------------------------------
    -- 1.1) نوع close  → یعنی این موجودیت واقعاً بسته است
    SELECT MAX(r.penalty_w)
    INTO v_admin_close_penalty
    FROM admin_restrictions r
    WHERE
