                -- یا محدودیت عمومی روی یک محدوده/طبقه
                (
                    r.target_table IS NULL
                    AND r.target_id   IS NULL
                    AND (r.floor IS NULL OR r.floor = p_floor)
                    AND (
                           r.geom IS NULL
                        OR (p_geom IS NOT NULL AND ST_Contains(r.geom, p_geom))
                    )
                )
        );

    IF v_admin_close_penalty IS NOT NULL THEN
        v_allowed := false;
				v_penalty := GREATEST(COALESCE(v_penalty, 1.0), COALESCE(v_admin_close_penalty, 1.0));
        v_type    := 'admin_close';
    END IF;

    -- 1.2) نوع غیر close → به معنی «مجاز ولی با جریمه»
    SELECT MAX(r.penalty_w)
    INTO v_admin_penalty
    FROM admin_restrictions r
    WHERE
        r.is_active = true
        AND (r.starts_at IS NULL OR r.starts_at <= v_now)
        AND (r.ends_at   IS NULL OR v_now <= r.ends_at)
        AND (
              r.gender IS NULL
           OR r.gender = 'both'::gender_enum
           OR r.gender = p_gender
        )
        AND (
              r.modes IS NULL
           OR p_mode = ANY(r.modes)
        )
        AND r.restrict_type <> 'close'
        AND (
                (r.target_table = p_entity_table AND r.target_id = p_entity_id)
             OR (
                    r.target_table IS NULL
                    AND r.target_id   IS NULL
                    AND (r.floor IS NULL OR r.floor = p_floor)
                    AND (
                           r.geom IS NULL
                        OR (p_geom IS NOT NULL AND ST_Contains(r.geom, p_geom))
                    )
                )
        );

    IF v_admin_penalty IS NOT NULL THEN
				v_penalty := GREATEST(COALESCE(v_penalty, 1.0), COALESCE(v_admin_penalty, 1.0));
        IF v_type = 'none' THEN
            v_type := 'admin_penalty';
        ELSIF v_type <> 'admin_close' THEN
            -- اگر قبلاً نوع دیگری هم ست شده بود، بگیم mixed
            v_type := 'mixed';
        END IF;
    END IF;

    ----------------------------------------------------------------------
    -- 2) محدودیت‌های زمانی (access_time_restrictions)
    --    این‌ها را به صورت «بسته بودن در این زمان» تفسیر می‌کنیم.
    ----------------------------------------------------------------------
    SELECT EXISTS (
        SELECT 1
        FROM access_time_restrictions r
        WHERE
            r.entity_table = p_entity_table
            AND r.entity_id = p_entity_id
            AND (r.specific_date IS NULL OR r.specific_date = v_date)
            AND (
                    r.all_hours = true
                 OR (
