    IF v_time_block_exists THEN
        v_allowed := false;
				v_penalty := GREATEST(COALESCE(v_penalty, 1.0), COALESCE(c_time_penalty, 1.0));

        IF v_type = 'none' THEN
            v_type := 'time';
        ELSIF v_type <> 'time' THEN
            v_type := 'mixed';
        END IF;
    END IF;

    ----------------------------------------------------------------------
    -- 3) محدودیت‌های نماز (access_prayer_restrictions)
    --    این بخش اسکلت است و به تابع زمان نماز نیاز دارد.
    --    فعلاً فقط TODO است؛ اگر تابع prayer windows رو اضافه کردی،
    --    این بخش را از حالت کامنت خارج کن.
    ----------------------------------------------------------------------

    -- نمونه‌ی پیشنهادی:
    -- یک تابع مثل:
    --   fn_prayer_windows(p_date date)
    -- که برای هر نماز، این خروجی را داشته باشد:
    --   (prayer_event text, center_time timestamptz)
    --
    -- سپس:
    /*
    SELECT EXISTS (
        SELECT 1
        FROM access_prayer_restrictions pr
        JOIN fn_prayer_windows(v_date) pw
             ON pw.prayer_event = pr.prayer_event
        WHERE
            pr.entity_table = p_entity_table
            AND pr.entity_id = p_entity_id
            AND (pr.specific_date IS NULL OR pr.specific_date = v_date)
            AND v_now BETWEEN
                (pw.center_time - make_interval(mins := pr.before_minutes))
                AND
                (pw.center_time + make_interval(mins := pr.after_minutes))
            AND (
                    pr.gender IS NULL
                 OR cardinality(pr.gender) = 0
                 OR p_gender = ANY(pr.gender)
                 OR 'both'::gender_enum = ANY(pr.gender)
            )
    ) INTO v_prayer_block_exists;
    */
		
		SELECT EXISTS (
    SELECT 1
    FROM access_prayer_restrictions pr
    WHERE pr.entity_table = p_entity_table
      AND pr.entity_id = p_entity_id
      AND (pr.specific_date IS NULL OR pr.specific_date = v_date)
      AND (
           pr.gender IS NULL OR cardinality(pr.gender)=0
        OR p_gender = ANY(pr.gender) OR 'both'::gender_enum = ANY(pr.gender)
      )
      AND (
        -- window check
        fn_prayer_event_time(v_date, pr.prayer_event) IS NOT NULL
        AND v_now_local BETWEEN
  (v_date_local::timestamp + fn_prayer_event_time(v_date_local, pr.prayer_event))
    - make_interval(mins => pr.before_minutes)
  AND
  (v_date_local::timestamp + fn_prayer_event_time(v_date_local, pr.prayer_event))
    + make_interval(mins => pr.after_minutes)

      )
  ) INTO v_prayer_block_exists;

    -- فعلاً تا وقتی تابع نماز را نداری، v_prayer_block_exists همیشه false می‌ماند.
    --v_prayer_block_exists := false;

    IF v_prayer_block_exists THEN
        v_allowed := false;
				v_penalty := GREATEST(COALESCE(v_penalty, 1.0), COALESCE(c_prayer_penalty, 1.0));
	
        IF v_type = 'none' THEN
            v_type := 'prayer';
        ELSIF v_type <> 'prayer' THEN
            v_type := 'mixed';
        END IF;
    END IF;

    ----------------------------------------------------------------------
    -- 4) خروجی
    ----------------------------------------------------------------------
    allowed          := COALESCE(v_allowed, true);
penalty_w        := COALESCE(v_penalty, 1.0);
restriction_type := COALESCE(v_type, 'none');

RETURN NEXT;
RETURN;

END;
$function$

