      loc_o.floor, loc_d.floor;
  END IF;

  -- ۲) فقط خروجی NavMesh را پاس بده، بدون هیچ دستکاری هندسه
  RETURN QUERY
    SELECT *
    FROM fn_route_walk_navmesh(
      p_now,
      p_gender,
      p_mode,
      loc_o.floor,
