  ------------------------------------------------------------
  CREATE TEMP TABLE tmp_dijkstra (
    node_id bigint PRIMARY KEY,
    cost    numeric,
    prev    bigint,
    visited boolean DEFAULT false
  ) ON COMMIT DROP;

  INSERT INTO tmp_dijkstra(node_id, cost, prev, visited)
