  WITH ordered AS (
    SELECT node_id, ord
    FROM tmp_path_nodes
    ORDER BY ord DESC
  ),
  pts AS (
    SELECT rn.geom AS pt_geom, o.ord
    FROM ordered o
    JOIN routing_nodes rn ON rn.id = o.node_id
    ORDER BY o.ord
  ),
